var l=[{title:`Чому важливий скринінг`,text:`Більшість людей виграють від більшої активності, і м’який рух часто є хорошим початком. Симптоми, нестабільні захворювання чи нещодавні медичні події можуть змінювати, які види активності для вас безпечні. Скринінг підказує, коли лікар чи кваліфікований фахівець із вправ має скерувати ваші наступні кроки.`},{title:`PAR-Q+`,text:`Чинний Опитувальник готовності до фізичної активності для всіх (PAR-Q+) використовує структуровані запитання про здоров’я з подальшими шляхами, тож виходить за межі одного загального чек-листа. Подумайте про захворювання серця чи судин, неконтрольований тиск, непритомність чи незрозумілі запаморочення, дискомфорт у грудях, нещодавню операцію, новий чи наростаючий біль і ліки, що змінюють реакцію тіла на вправи. Вагітність і місяці після пологів також потребують індивідуальної поради.`},{title:`Що означає відповідь «так»`,text:`Відповідь «так» на запитання скринінгу автоматично не означає «жодних вправ». Вона може означати завершення офіційного подальшого процесу чи отримання поради щодо інтенсивності й обмежень. Якщо ви вже безпечно тренуєтеся, продовження на знайомому рівні є іншим рішенням, ніж початок важких тренувань, яких ви ніколи не робили.`},{title:`Приклад`,text:`Людина, яка роками була неактивною та відчуває тиск у грудях під час швидкої ходьби, не повинна пробувати максимальне силове чи інтервальне заняття. Їй слід припинити цю активність і пройти медичне обстеження. Сильні чи тривалі симптоми в грудях потребують невідкладної допомоги. Людина без тривожних симптомів може почати з легкої ходьби та легкої силової практики, а потім поступово нарощувати.`},{title:`Використання TrainUp`,text:`Ви можете записати обмеження за ділянками тіла в Профілі, з нотатками, і план добере лише вправи, що їм відповідають. TrainUp не може підтвердити відсутність медичного стану чи тлумачити ваші симптоми, а згенероване тренування не є медичним дозволом. Якщо скринінг викликає занепокоєння, запитайте лікаря, перш ніж обирати вимогливий план.`}];var i=[{label:`Офіційний скринінг PAR-Q+`,url:`https://eparmedx.com/`},{label:`CDC: як почати`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var a={sections:l,sources:i};export{a as default,l as sections,i as sources};